head.script:
scwin.regMode;
scwin.gIsurCd;
scwin.gSeq;
scwin.gChgBfafTpCd;
scwin.gDesignRsnCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.getParentValue();
        await scwin.init();

        // if(regMode == 'MOD'){
        await scwin.readInfo(); // 기본정보 불러오기
        // }

        $c.stf.doLogSave('ULDSTF37711.xml', SCREN_PROCS_TP_CD_01);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37711.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    if (scwin.gDesignRsnCd === "4" || scwin.gDesignRsnCd === "5" || scwin.gDesignRsnCd === "6") {
        img_cls_dd.show("");
        edt_strt_dd.setReadOnly(false);
    } else {
        img_cls_dd.hide();
        edt_strt_dd.setReadOnly(true);
    }

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MASTER.insertRow();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_cls_dd_onclick
 * @description img_cls_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_cls_dd_onclick = function() {
    try {
        popUpCalendar2(edt_strt_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37711.img_cls_dd_onclick" });
    }
};

/**
 * @method
 * @name trs_inquiry_OnSuccess
 * @description inquiry On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37711.trs_inquiry_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_inquiry_OnFail
 * @description inquiry On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnFail = async function() {
    try {
        await $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37711.trs_inquiry_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37711.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37711.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readInfo
 * @description 선택한 정보 값 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ConfrmProcs.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name insert
 * @description 등록 및 수정 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    const vStrt_dd = edt_strt_dd.getValue();

    // 매매일 체크
    if (!$c.lc.fn_TrHoldyYn(dts_checkDD, vStrt_dd)) {
        edt_strt_dd.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(txb_design_rsn_dsc, 100, "비고")) {
        // txb_design_rsn_dsc.value = "";
        txb_design_rsn_dsc.focus();
        return false;
    }

    // 메세지 설정
    let tmpStr;
    tmpStr = "저장 하시겠습니까?";
    const vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_inquiry.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_inquiry",
            action : "/ConfrmProcs.do",
            ref : "dts_MASTER",
            target : "trs_inquiry=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gSeq = frame.opener.scwin.gSeq;
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gChgBfafTpCd = frame.opener.scwin.gChgBfafTpCd;
    scwin.gDesignRsnCd = frame.opener.scwin.gDesignRsnCd;
    txb_seq.setValue(scwin.gSeq);
    txb_isur_cd.setValue(scwin.gIsurCd);
    txb_chg_bfaf_tp_cd.setValue(scwin.gChgBfafTpCd);
    txb_designRsnCd.setValue(scwin.gDesignRsnCd);
    txb_seq.hide();
    txb_chg_bfaf_tp_cd.hide();
    txb_designRsnCd.hide();
};

/**
 * @method
 * @name strAppend
 * @description saveVar의 값이 비어있을경우 sVar를 그대로 리턴, 비어있지 않을경우 ','를 붙여 리턴
 * @param {*} saveVar saveVar
 * @param {*} sVar sVar
 * @returns {void}
 * @hidden N
 */
scwin.strAppend = function(saveVar, sVar) {
    if (saveVar === '') {
        return sVar;
    } else {
        return "," + sVar;
    }
};

/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
